const now = new Date();
const istOffset = 5.5 * 3600000;
const nowIst = new Date(now.getTime() + istOffset);
const todayIst = new Date(Date.UTC(nowIst.getUTCFullYear(), nowIst.getUTCMonth(), nowIst.getUTCDate()));
const yesterdayIst = new Date(todayIst.getTime() - 86400000);
const target_date = yesterdayIst.toISOString().slice(0,10);
return [{ json: { target_date } }];

const d = $('Compute Target Date').first().json.target_date;
const query = `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
JOIN (
  SELECT cd.service_id, cd.missed_by AS agent_name, cd.call_date, COUNT(*) AS agent_missed_ib
  FROM calls.call_disposition cd
  WHERE cd.call_type='INBOUND' AND cd.disposition='Agent Missed' AND (cd.service_id <> 1287 OR cd.ivr = 'Appointement/Other') AND cd.call_date = '${d}'
    AND EXISTS (SELECT 1 FROM calls.daywise_summary ds WHERE ds.service_id=cd.service_id AND ds.agent_name=cd.missed_by)
  GROUP BY cd.service_id, cd.missed_by, cd.call_date
) ami ON ami.service_id = dp.service_id AND ami.agent_name = cs.agent AND ami.call_date = cs.report_date
SET cs.agent_missed_ib = ami.agent_missed_ib
WHERE cs.report_date = '${d}';`;
return [{ json: { query } }];

const d = $('Compute Target Date').first().json.target_date;
const query = `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
JOIN (
  SELECT cd.service_id, cd.agent_number AS sip, cd.call_date, ROUND(AVG(cd.handle_time_sec)) AS aht_seconds
  FROM calls.call_disposition cd
  WHERE cd.call_type='INBOUND' AND cd.disposition='Answer' AND (cd.service_id <> 1287 OR cd.ivr = 'Appointement/Other') AND cd.call_date = '${d}'
    AND EXISTS (SELECT 1 FROM calls.daywise_summary ds WHERE ds.service_id=cd.service_id AND ds.agent_sip=cd.agent_number)
  GROUP BY cd.service_id, cd.agent_number, cd.call_date
) aht ON aht.service_id = dp.service_id AND aht.sip = cs.sip AND aht.call_date = cs.report_date
SET cs.aht = SEC_TO_TIME(aht.aht_seconds)
WHERE cs.report_date = '${d}';`;
return [{ json: { query } }];

const d = $('Compute Target Date').first().json.target_date;
const query = `UPDATE calls.combined_summary cs
JOIN calls.dim_process dp ON dp.process_name = cs.process_name
JOIN calls.callback_on_missed_call cb ON cb.service_id = dp.service_id AND cb.report_date = cs.report_date
SET cs.callback_on_missed_call = SEC_TO_TIME(cb.avg_gap_seconds)
WHERE cs.report_date = '${d}';`;
return [{ json: { query } }];
